#include <iterator>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    int values[]{1, 2, 3};
    std::basic_const_iterator position{values};
    assert(*position == 1 && position[1] == 2 && position.base() == values);
    auto copy = position;
    ++position;
    --position;
    position += 1;
    position -= 1;
    assert(position == copy && position - copy == 0 && copy + 1 == 1 + copy);
    assert(std::ranges::iter_move(copy) == 1);
    using Common = std::common_type_t<decltype(copy), const int *>;
    (void)sizeof(Common);
}
